x=np.array([2.,-1.5,.5,3.,-1.]);y=np.array([3.4,-2.8,.2,5.1,-1.4]);b,a=np.polyfit(x,y,1);xx=np.linspace(-1.8,3.3,100);ax.scatter(x,y,color=ACCENT,s=35,label='monthly observations');ax.plot(xx,a+b*xx,color=BAD,lw=2,label='OLS fit');[ax.plot([u,u],[v,a+b*u],ls='--',color=MUTED,lw=1) for u,v in zip(x,y)];ax.scatter([x.mean()],[y.mean()],color=GOOD,s=48,label='sample means');ax.set_xlabel('SPY return (percentage points/month)');ax.set_ylabel('AAPL return (percentage points/month)');ax.legend(fontsize=7);ax.set_title('Vertical gaps are prediction errors in y units',loc='left')
